let statement =
  `let deriv =
     \(g:real->real) (x:real). @d. (g diffl d) x in
   !f:real->real. !a b:real.
     (!x. f differentiable x) /\
     (!x. deriv f differentiable x) /\
     (!x. a <= x /\ x <= b ==> abs(f x) <= &1) /\
     (!x. a <= x /\ x <= b ==> abs(deriv (deriv f) x) <= &1) /\
     b - a >= &2
     ==> !x. a <= x /\ x <= b ==> abs(deriv f x) <= &2`;;

