let statement =
  `let putnam_1962_a5_solution =
     \n:num. n * (n + 1) * 2 EXP (n - 2) in
   !n:num.
     2 <= n
     ==> putnam_1962_a5_solution n =
         nsum (1..n) (\k. binom (n,k) * k EXP 2)`;;

