let statement =
  `!n:num. !a b:num->real. !xs:real->bool. !f:real->real.
     f =
       (\x. sum (0..n)
                (\k. a k * sin (&k * x) +
                     b k * cos (&k * x))) /\
     (!x. &0 <= x /\ x <= &2 * pi ==> abs (f x) <= &1) /\
     xs HAS_SIZE (2 * n) /\
     xs SUBSET {x | &0 <= x /\ x < &2 * pi} /\
     (!x. x IN xs ==> abs (f x) = &1)
     ==> (~(?c:real. f = (\x. c))
          ==> ?alpha:real. f = (\x. cos (&n * x + alpha)))`;;

