let statement =
  `let unit_interval = {x:real | &0 <= x /\ x <= &1} in
   let continuous_on =
     \(f:real->real) (s:real->bool).
       !x. x IN s
           ==> !e. &0 < e
                   ==> ?d. &0 < d /\
                           !y. y IN s /\ abs (y - x) < d
                               ==> abs (f y - f x) < e in
   let solution = \alpha:real. {}:(real->real)->bool in
   !alpha:real.
     solution alpha =
     {f:real->real |
        (!x. x IN unit_interval ==> &0 < f x) /\
        continuous_on f unit_interval /\
        integral(&0,&1) f = &1 /\
        integral(&0,&1) (\x. x * f x) = alpha /\
        integral(&0,&1) (\x. x pow 2 * f x) = alpha pow 2}`;;

(*
  Statement-only formalization of PutnamBench artifact putnam_1964_a3:
  the sum of the cubic products of the two new interval lengths formed by an
  injective dense sequence in (0,1) is 1/3. This file contains no proof.
*)

let analysis_output = open_out "/dev/null";;
