let statement =
  `?k:real.
     !a:num->real.
       (!n:num. &0 < a n) /\
       summable (\n:num. &1 / a n)
       ==> ?L1 L2:real.
             (\n:num. &(n + 1) / sum (0..n) a) sums L1 /\
             (\n:num. &1 / a n) sums L2 /\
             L1 <= k * L2`;;

