let statement =
  `!n:num.
     0 < n
     ==> sum (0..(n - 1) DIV 2)
             (\r. (&(n - 2 * r) * &(binom (n,r)) / &n) pow 2) =
         &(binom (2 * n - 2,n - 1)) / &n`;;

