let statement =
  `!a:num->real. !alpha:complex.
     (((\n:num. sum (1..n) (\k. cos(a k)) / &n)
         tends_num_real Re(alpha)) /\
       ((\n:num. sum (1..n) (\k. sin(a k)) / &n)
         tends_num_real Im(alpha)) <=>
      ((\n:num. sum (1..(n EXP 2)) (\k. cos(a k)) / &(n EXP 2))
         tends_num_real Re(alpha)) /\
       ((\n:num. sum (1..(n EXP 2)) (\k. sin(a k)) / &(n EXP 2))
         tends_num_real Im(alpha)))`;;

