let statement =
  `!u v m:real.
     &0 < u /\ &0 < v /\ &1 < m
     ==>
     (((?x y:real.
          &0 < x /\
          &0 < y /\
          u * x + v * y = &1 /\
          exp (m * ln x) + exp (m * ln y) = &1 /\
          u = exp ((m - &1) * ln x) /\
          v = exp ((m - &1) * ln y)) <=>
       (?n:real.
          exp (n * ln u) + exp (n * ln v) = &1 /\
          &1 / m + &1 / n = &1)))`;;

