       integral(&0,&1) (\x. g (s + x)) in
   let cube_integral =
     \n:num.
       ITER (n + 1) integrate_one
         (\s. (cos (pi / (&2 * &(n + 1)) * s)) pow 2) (&0) in
   cube_integral tends_num_real (&1 / &2)`;;

